class User {
  role = 'user'; // 1-й шаг
  constructor() {
    console.log(this.role); // 'user' (2-й шаг)
  }
}

class Admin extends User {
  level = 1; // 2-й шаг (после super)
  constructor() {
    super(); // 1-й шаг
    console.log(this.level); // 1 (3-й шаг)
  }
}

class Btn {
  val = 'OK';
  click() { console.log(this.val); }
  arrowClick = () => console.log(this.val);
}
